refused_program.body:
git merge --no-edit {upstream_remote}/{upstream_branch} >/dev/null 2>&1 || true
tmp=$(mktemp -d)
git diff --name-only --diff-filter=U -z | tr '\0' '\n' > "$tmp/conflicted"
while IFS= read -r f; do
  [ -n "$f" ] || continue
  if git rev-parse -q --verify ":1:$f" >/dev/null 2>&1 \
     && git rev-parse -q --verify ":2:$f" >/dev/null 2>&1 \
     && git rev-parse -q --verify ":3:$f" >/dev/null 2>&1; then
    base=$(git rev-parse ":1:$f")
    ours=$(git rev-parse ":2:$f")
    theirs=$(git rev-parse ":3:$f")
    git cat-file blob "$ours" > "$tmp/ours"
    git cat-file blob "$theirs" > "$tmp/theirs"
    git diff -U0 "$base" "$ours" > "$tmp/diff"
    awk -v oursfile="$tmp/ours" -v theirsfile="$tmp/theirs" '
function firsttok(s,   t, p) {
  t = s
  sub(/^[ \t]+/, "", t)
  p = index(t, " ")
  if (p == 0) return t
  return substr(t, 1, p - 1)
}
function findfirst(s,   j) {
  for (j = 1; j <= nt; j++) if (!del[j] && t[j] == s) return j
  return 0
}
function findanchor(ai,   p, best, bestscore, j, k, q, s) {
  best = 0
  bestscore = -1
  for (j = 1; j <= nt; j++) {
    if (del[j]) continue
    if (t[j] != o[ai]) continue
    s = 0
    k = ai - 1
    q = j - 1
    while (k >= 1 && q >= 1 && t[q] == o[k] && !del[q]) { s++; k--; q-- }
    if (s > bestscore) { bestscore = s; best = j }
  }
  return best
}
function insafter(p, text,   k, n, lines, j) {
  n = split(text, lines, "\n")
  for (k = n; k >= 1; k--) {
    if (lines[k] == "") continue
    for (j = nt; j >= p + 1; j--) { t[j + 1] = t[j]; del[j + 1] = del[j] }
    t[p + 1] = lines[k]
    del[p + 1] = 0
    nt++
  }
}
function dohunk(   i, j, k) {
  if (!inh) return
  for (i = 1; i <= nm; i++) mstate[i] = 0
  for (i = 1; i <= np; i++) pstate[i] = 0
  for (i = 1; i <= np; i++) {
    for (j = 1; j <= nm; j++) {
      if (mstate[j]) continue
      if (firsttok(minus[j]) == firsttok(plus[i])) { mstate[j] = 1; pstate[i] = j; break }
    }
  }
  for (j = 1; j <= nm; j++) {
    if (mstate[j]) continue
    k = findfirst(minus[j])
    if (k > 0) del[k] = 1
  }
  for (i = 1; i <= np; i++) {
    j = pstate[i]
    if (j > 0) {
      k = findfirst(minus[j])
      if (k > 0) t[k] = plus[i]
    } else {
      addn++
      addpos[addn] = c
      addtext[addn] = plus[i]
    }
  }
  inh = 0
  nm = 0
  np = 0
}
FILENAME == oursfile { o[++no] = $0; next }
FILENAME == theirsfile { t[++nt] = $0; next }
/^@@ / {
  dohunk()
  split(substr($2, 2), A, ",")
  split(substr($3, 2), B, ",")
  c = B[1] + 0
  inh = 1
  next
}
{
  if (!inh) next
  if (substr($0, 1, 1) == "-") { minus[++nm] = substr($0, 2); next }
  if (substr($0, 1, 1) == "+") { plus[++np] = substr($0, 2); next }
}
END {
  dohunk()
  for (k = addn; k >= 1; k--) {
    ai = addpos[k] - 1
    p = 0
    while (ai >= 1) {
      p = findanchor(ai)
      if (p > 0) break
      ai--
    }
    insafter(p, addtext[k])
  }
  for (j = 1; j <= nt; j++) if (!del[j]) print t[j]
}
' "$tmp/ours" "$tmp/theirs" "$tmp/diff" > "$tmp/merged"
    cat "$tmp/merged" > "$f"
    git add -- "$f"
  else
    if git checkout --theirs -- "$f" >/dev/null 2>&1; then
      git add -- "$f"
    else
      git rm -q -f -- "$f" >/dev/null 2>&1 || true
    fi
  fi
done < "$tmp/conflicted"
rm -rf "$tmp"
if git rev-parse -q --verify MERGE_HEAD >/dev/null 2>&1; then
  git commit --no-edit >/dev/null
fi
